enum BookState {
  BOOK_STATE_UNSPECIFIED = 0;
  BOOK_STATE_ACTIVE = 1;
  BOOK_STATE_DELETING = 2;
  BOOK_STATE_DELETED = 3;
}

message Book {
  option (google.api.resource) = {
    type: "library.protoform.dev/Book"
    pattern: "publishers/{publisher}/books/{book}"
    singular: "book"
    plural: "books"
  };

  string name = 1 [(google.api.field_behavior) = IDENTIFIER];
  string uid = 2 [(google.api.field_behavior) = OUTPUT_ONLY];
  string display_name = 3 [(google.api.field_behavior) = REQUIRED];
  google.protobuf.Timestamp create_time = 4 [
    (google.api.field_behavior) = OUTPUT_ONLY
  ];
  google.protobuf.Timestamp update_time = 5 [
    (google.api.field_behavior) = OUTPUT_ONLY
  ];
  google.protobuf.Timestamp delete_time = 6 [
    (google.api.field_behavior) = OUTPUT_ONLY
  ];
  // ISBN-13 digits. The CEL rule enforces the alternating 1/3 checksum.
  string isbn = 7 [
    (google.api.field_behavior) = IMMUTABLE,
    (buf.validate.field).required = true,
    (buf.validate.field).string.pattern = "^[0-9]{13}$",
    (buf.validate.field).cel = {
      id: "book.isbn13_check_digit"
      message: "ISBN must have a valid ISBN-13 check digit."
      expression: "!this.matches('^[0-9]{13}$') || (int(this.substring(0, 1)) + int(this.substring(1, 2)) * 3 + int(this.substring(2, 3)) + int(this.substring(3, 4)) * 3 + int(this.substring(4, 5)) + int(this.substring(5, 6)) * 3 + int(this.substring(6, 7)) + int(this.substring(7, 8)) * 3 + int(this.substring(8, 9)) + int(this.substring(9, 10)) * 3 + int(this.substring(10, 11)) + int(this.substring(11, 12)) * 3 + int(this.substring(12, 13))) % 10 == 0"
    }
  ];
  string input_token = 8 [(google.api.field_behavior) = INPUT_ONLY];
  optional string note = 9 [(google.api.field_behavior) = OPTIONAL];
  string etag = 10 [(google.api.field_behavior) = OUTPUT_ONLY];
  oneof expiration {
    google.protobuf.Timestamp expire_time = 11;
    google.protobuf.Duration ttl = 12 [
      (google.api.field_behavior) = INPUT_ONLY
    ];
  }
  BookState state = 13 [(google.api.field_behavior) = OUTPUT_ONLY];
  google.protobuf.Timestamp purge_time = 14 [
    (google.api.field_behavior) = OUTPUT_ONLY
  ];
}

