message ProvisionCapacityRequest {
  // Storage capacity in binary gibibytes (GiB).
  int64 storage_gibibytes = 1 [
    (google.api.field_behavior) = REQUIRED,
    (buf.validate.field).int64.gte = 0
  ];

  // Number of replicas to provision.
  int32 replica_count = 2 [
    (google.api.field_behavior) = REQUIRED,
    (buf.validate.field).int32.gte = 0
  ];

  // ISO 4217 currency code, such as GBP.
  // https://www.iso.org/iso-4217-currency-codes.html
  optional string currency_code = 3 [
    (buf.validate.field).string.pattern = "^[A-Za-z]{3}$"
  ];

  // BCP 47 language code, such as en-GB.
  // https://www.rfc-editor.org/info/bcp47
  optional string language_code = 4 [
    (buf.validate.field).string.pattern = "^[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*$"
  ];

  // CLDR region code, such as GB.
  // https://unicode.org/cldr/charts/latest/supplemental/territory_information.html
  optional string region_code = 5 [
    (buf.validate.field).string.pattern = "^[A-Za-z]{2}$"
  ];

  // IANA time zone identifier, such as Europe/London.
  // https://www.iana.org/time-zones
  optional string time_zone = 6 [
    (buf.validate.field).string.pattern = "^[A-Za-z._+-]+(/[A-Za-z0-9._+-]+)+$"
  ];
}

message TimeRange {
  option (buf.validate.message).cel = {
    id: "aip145.time_range"
    message: "end time must be later than start time"
    expression: "!has(this.start_time) || !has(this.end_time) || this.start_time < this.end_time"
  };

  // Inclusive start of the time range. Omit for an open lower bound.
  optional google.protobuf.Timestamp start_time = 1;

  // Exclusive end of the time range. Omit for an open upper bound.
  optional google.protobuf.Timestamp end_time = 2;
}

